{"path":"creative_intent.json","content":"{
  "user_need": "警察男主绑定'犯罪预警系统'，能在凶手额头看到倒计时。他发现未婚妻（法医）额头显示'将在今晚23:00杀害你'。系统提示'不可更改'。他必须在12小时内破解这个'未来命案'，同时不能让她发现他在防备她。随着调查，他发现她杀他的动机是为了阻止他去救一个会导致更大灾难的证人（D20为理想牺牲）。12万字，高密度悬疑。",
  "inspiration_state": "clear_inspiration",
  "extracted_elements": {
    "emotion_verbs": ["牺牲", "防备", "破解", "阻止", "拯救", "信任崩塌"],
    "scene_elements": ["警察", "法医", "犯罪预警系统", "倒计时", "证人", "病毒零号病人", "犯罪集团", "12小时", "未来命案"],
    "relationship_tension": ["未婚夫妻", "相爱相杀", "信任与防备的矛盾", "为救对方而伤害对方", "深爱却必须为敌"],
    "user_preferences": {
      "desired_emotion": "高密度悬疑、道德困境、窒息感、深爱却必须为敌",
      "forbidden": ["不要简单化处理", "不要轻易和解", "不要削弱道德困境的残酷性"]
    }
  },
  "selected_recipe": {
    "x_axis_mode_id": "D20",
    "x_axis_mode_name": "为理想牺牲",
    "y_axis_tags": ["系统流", "刑侦悬疑"],
    "reaction_strength": "↘",
    "tension_stars": 4,
    "forbidden_elements": [
      "不要简单化处理道德困境",
      "不要轻易让两人和解",
      "不要削弱'救一人还是救苍生'的残酷性",
      "不要让系统成为简单的金手指",
      "不要让病毒威胁显得虚假或夸大"
    ],
    "x_axis_display": "未婚妻为阻止病毒扩散（救苍生）必须杀他（牺牲小爱），他为破解命案必须防备她，两人都为理想/大义而牺牲爱情，形成无法调和的道德困境",
    "y_axis_combination_effect": "系统流的'不可更改'规则加剧道德困境，刑侦悬疑的12小时倒计时制造窒息感，两者结合让'深爱却必须为敌'的张力达到极致",
    "reaction_formula": "系统预警增加道德困境，她为阻止灾难必须杀他，他为破解命案必须防备她，相爱相杀的悲剧美学",
    "platform_fit": ["起点", "豆瓣阅读", "知乎盐选"]
  },
  "one_sentence_synopsis": "警察发现未婚妻将在12小时内杀他，破解真相后陷入'救一人还是救苍生'的道德死局。"
}"}

{"path":"characters.json","content":"{
  "main_characters": [
    {
      "name": "沈翊",
      "role": "protagonist",
      "identity": "刑警队长，32岁，犯罪预警系统绑定者",
      "traits": ["理性敏锐", "责任感强", "深信系统", "信任爱人", "内心脆弱"],
      "overt_motivation": "破解'未来命案'，保护证人，阻止犯罪集团",
      "covert_motivation": "证明系统预言可以改变，守护与林清的爱情",
      "secret_fear": "失去林清，系统预言成真，自己成为命运的囚徒",
      "misperception_of_other": "认为林清可能被犯罪集团胁迫，或对证人有误解，不知道她已发现病毒真相",
      "hidden_connection": "三年前与林清共同侦破一起连环杀人案，那次经历让他深信'真相可以拯救一切'"
    },
    {
      "name": "林清",
      "role": "deuteragonist",
      "identity": "法医，30岁，沈翊的未婚妻",
      "traits": ["冷静专业", "理性极致", "内心挣扎", "为大局牺牲", "深爱沈翊"],
      "overt_motivation": "阻止病毒扩散，保护更多人的生命",
      "covert_motivation": "保护沈翊不成为'导致灾难的人'，即使代价是亲手杀他",
      "secret_fear": "沈翊发现真相后理解她，那她将无法下手；或者沈翊不理解她，带着恨意死去",
      "misperception_of_other": "认为沈翊会坚持'程序正义'去救证人，不知道他也在挣扎于'救一人还是救苍生'",
      "hidden_connection": "通过尸检上一名受害者发现病毒特征，推断出证人是零号病人，但无法在不暴露证人位置的情况下预警"
    }
  ],
  "supporting_characters": [
    {
      "name": "陈宇",
      "function": "反转点",
      "identity": "犯罪集团核心成员，携带新型高致死率病毒的'零号病人'，掌握集团核心名单",
      "description": "表面是普通证人，实则是病毒携带者。一旦警方介入保护并转移他，病毒将在人口密集区扩散，造成大规模死亡。他本人并不知情自己是零号病人。"
    },
    {
      "name": "周明",
      "function": "助力",
      "identity": "沈翊的搭档，刑警",
      "description": "忠诚可靠，但不知道系统的存在，也不知道病毒真相。在沈翊最挣扎时提供情感支持。"
    },
    {
      "name": "系统",
      "function": "阻碍",
      "identity": "犯罪预警系统，神秘的超自然存在",
      "description": "显示凶手额头倒计时，提示'不可更改'。它的规则是绝对的，但它的目的未知。是命运的使者，还是某种更高维度的存在？"
    }
  ],
  "relationship_dynamics": "沈翊与林清是未婚夫妻，深爱彼此，但系统预言将他们推向对立面。沈翊在信任与怀疑之间挣扎，林清在爱与责任之间撕裂。两人都想保护对方，却不得不成为彼此的敌人。'深爱却必须为敌'的窒息感贯穿始终。"
}"}

{"path":"outline.json","content":"{
  "act_one": {
    "description": "建立世界观：犯罪预警系统、警察工作、未婚妻关系。引入核心冲突：沈翊发现林清额头显示'将在今晚23:00杀害你'，系统提示'不可更改'。他在震惊中开始调查，发现林清的异常行为，信任开始动摇。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "倒计时",
        "core_event": "沈翊在晨光中醒来，看到林清额头浮现血红色倒计时：'将在今晚23:00杀害你'。系统提示'不可更改'。他震惊、恐惧，但必须假装一切正常。",
        "emotional_tone": "震惊、恐惧、窒息",
        "key_scenes": ["晨起看到倒计时", "系统提示'不可更改'", "假装正常吃早餐", "林清的温柔让他心碎"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "日常的裂痕",
        "core_event": "沈翊去警局，试图集中精力工作，但倒计时时刻在他脑海。他开始观察林清的异常：她最近加班频繁，尸检报告有隐瞒，手机有加密文件。",
        "emotional_tone": "怀疑、挣扎、压抑",
        "key_scenes": ["警局日常工作", "观察林清的异常", "查看尸检报告", "发现加密文件"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "证人的线索",
        "core_event": "沈翊接到任务：保护证人陈宇，他掌握犯罪集团核心名单。沈翊发现林清对陈宇的案件异常关注，甚至试图接触证人的保护记录。",
        "emotional_tone": "紧张、困惑、不安",
        "key_scenes": ["接到保护证人任务", "林清对证人的异常关注", "试图接触保护记录", "沈翊的怀疑加深"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "试探",
        "core_event": "沈翊试探林清：问她最近在忙什么，为什么对证人案件感兴趣。林清的回答含糊其辞，沈翊感到她在隐瞒什么，但不知道是什么。",
        "emotional_tone": "试探、压抑、痛苦",
        "key_scenes": ["晚餐时的试探", "林清的含糊回答", "沈翊的内心挣扎", "信任开始裂痕"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "系统的规则",
        "core_event": "沈翊研究系统的规则：倒计时一旦出现，就不可更改。他试图寻找先例，发现所有案例都成真。但他不甘心，决定打破这个'命运'。",
        "emotional_tone": "绝望、不甘、决心",
        "key_scenes": ["研究系统规则", "查找先例", "所有案例都成真", "决定打破命运"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "林清的秘密",
        "core_event": "沈翊偷偷查看林清的加密文件，发现她在研究一种新型病毒。他不知道这与证人有关，但感到事态严重。",
        "emotional_tone": "紧张、恐惧、困惑",
        "key_scenes": ["偷偷查看加密文件", "发现病毒研究", "事态严重", "沈翊的恐惧加深"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "倒计时的压迫",
        "core_event": "时间流逝，倒计时从12小时变成8小时。沈翊感到窒息，他必须在有限时间内找到真相，同时不能让林清发现他在防备她。",
        "emotional_tone": "窒息、紧迫、焦虑",
        "key_scenes": ["倒计时减少", "时间压迫感", "不能暴露防备", "内心煎熬"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "信任的崩塌",
        "core_event": "沈翊发现林清在偷偷跟踪证人保护小组的动向。他质问自己：她到底想做什么？她真的会杀我吗？信任开始崩塌。",
        "emotional_tone": "崩溃、痛苦、撕裂",
        "key_scenes": ["发现林清跟踪证人", "内心质问", "信任崩塌", "痛苦撕裂"]
      }
    ],
    "turning_point": "沈翊决定暗中调查林清的动机，同时继续执行保护证人的任务。他不知道，这两个选择将把他推向道德困境的深渊。"
  },
  "act_two": {
    "description": "冲突升级：沈翊在信任与怀疑之间挣扎，林清在爱与责任之间撕裂。两人开始互相试探，信任彻底崩塌。中点转折：沈翊发现证人陈宇携带病毒，是零号病人。转折点：林清揭示真相——救证人将导致病毒扩散，造成大规模死亡。",
    "key_chapters": [
      {
